def encode_cyclic(s: str):
    """
    Returns encoded string by cycling groups of three characters.
    """
    groups = [s[(i * 3):min((i + 1) * 3, len(s))] for i in range((len(s) + 2) // 3)]
    # Shift each group of 3 by moving the first character to the end
    shifted = []
    for group in groups:
        if len(group) == 3:
            shifted.append(group[1:] + group[0])
        else:
            shifted.append(group)  # Leave short groups as-is
    return "".join(shifted)

def decode_cyclic(s: str):
    """
    Decodes a string that was encoded with encode_cyclic by reversing the cyclic shift.
    For each group of 3 characters, the last character was originally first, so to decode,
    we move the last character of the 3-char group to the front.
    """
    groups = [s[(i * 3):min((i + 1) * 3, len(s))] for i in range((len(s) + 2) // 3)]
    decoded = []
    for group in groups:
        if len(group) == 3:
            decoded.append(group[-1] + group[:-1])  # Move last char to front
        else:
            decoded.append(group)  # Short groups unchanged
    return "".join(decoded)
