def encrypt(s):
    """
    Rotate the alphabet by 4 positions forward (since shifting by 2 places multiplied by 2).
    Non-alphabetic characters are left unchanged.
    """
    import string
    def rotate(c):
        if 'a' <= c <= 'z':
            # Calculate new code point with rotation of 4 (2*2)
            offset = ord('a')
            return chr((ord(c) - offset + 4) % 26 + offset)
        elif 'A' <= c <= 'Z':
            # Rotate uppercase letters as well
            offset = ord('A')
            return chr((ord(c) - offset + 4) % 26 + offset)
        else:
            # Non-alphabetic characters unchanged
            return c
    return ''.join(rotate(ch) for ch in s)

