def skjkasdkd(lst):
    """
    Finds the largest prime number in the input list and returns the sum of its digits.
    If there are no primes in the list, returns 0.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True  # 2 and 3 are primes
        if n % 2 == 0 or n % 3 == 0:
            return False
        # Check divisibility up to sqrt(n) using 6k ± 1 optimization
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0
    # Compute sum of digits
    return sum(int(d) for d in str(max_prime))
